@pytest.mark.parametrize("update", ["joint", "forward", "reverse"]) @pytest.mark.parametrize("mode", ["ordinary", "natural"]) @pytest.mark.parametrize("step", ["fixed", "backtracking"]) @pytest.mark.parametrize("count", [0, 3]) def test_recipe_matches_frozen_trajectory_and_retention(update, mode, step, count): train, validation, binned, _ = prepared_fixture("weighted") rate = 0.1 if step == "fixed" else 8 initial, expected = rounds( "weighted", depth=1, update=update, mode=mode, fixed=step == "fixed", rate=rate, count=count ) with ExecutionContext() as context: ops = DeviceOperations(context) result = recipes.normal( ops, train, validation, run_id="recipe", seed=7, rounds=count, update=update, mode=mode, step=step, learning_rate=rate, binning=binned.binning, max_depth=1, ) assert result.stop.completed_rounds == count and result.stop.reason == "budget" assert len(result.steps) == len(expected) before_version = 0 for actual, ref in zip(result.steps, expected, strict=True): assert actual.channels == ref["channels"] and actual.round_index == ref["round"] assert ( actual.before_version == before_version and actual.after_version == ref["version"] ) before_version = actual.after_version assert actual.accepted == ref["accepted"] assert actual.coefficients == tuple(float(np.float32(t[0])) for t in ref["attempts"]) assert actual.failures == (None,) * len(ref["attempts"]) assert actual.loss == pytest.approx(ref["loss"], rel=LOSS_RTOL, abs=LOSS_ATOL) for trial, expected_trial in zip(actual.trials, ref["attempts"], strict=True): assert trial.accepted == (expected_trial[2] == "accepted") assert trial.loss == pytest.approx(expected_trial[1], rel=LOSS_RTOL, abs=LOSS_ATOL) state, run = result.state, result.run close( raw(context, run, state), expected[-1]["raw"] if count else np.broadcast_to(initial, train.offset.shape), ) assert state.best_n_terms == (expected[-1]["best_terms"] if count else 0) assert len(run._states) == 1 and not run._proposals expected_bytes = sum(h.nbytes for record in run._prepared for h in ops._records[record][1]) expected_bytes += 8 + 8 * (run.data.n_rows + run.validation_data.n_rows) expected_bytes += sum(t.tree.n_nodes * 24 for t in run._states[state].terms) > assert context.metrics["live_bytes"] == expected_bytes E assert 536 == 472
